import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Streaming & Resilience","description":"","frontmatter":{"title":"Streaming & Resilience"},"headers":[],"relativePath":"concepts/streaming-resilience.md","filePath":"concepts/streaming-resilience.md"}'),s={name:"concepts/streaming-resilience.md"};function i(o,e,l,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<blockquote><p>🚧 Wingport is in active development. The API described here is the v0.1 design. Star the repo to follow along, or join the early access list.</p></blockquote><h1 id="streaming-resilience" tabindex="-1">Streaming &amp; Resilience <a class="header-anchor" href="#streaming-resilience" aria-label="Permalink to &quot;Streaming &amp; Resilience&quot;">​</a></h1><p>This is the half of the problem everyone underestimates. Mobile networks are hostile to long-lived SSE streams: WiFi↔cellular handoffs, elevators, app backgrounding, carrier NAT timeouts. Wingport&#39;s SDK treats stream failure as the <em>normal case</em> to engineer for, not an edge case.</p><h2 id="what-the-sdk-handles-for-you" tabindex="-1">What the SDK handles for you <a class="header-anchor" href="#what-the-sdk-handles-for-you" aria-label="Permalink to &quot;What the SDK handles for you&quot;">​</a></h2><ul><li><strong>Chunk reassembly.</strong> SSE events fragment across TCP packets; the parser handles partial frames, multi-line data, and keep-alive comments.</li><li><strong>Mid-stream network loss.</strong> If the connection drops mid-generation, the SDK surfaces the tokens received so far and throws <code>StreamInterruptedException</code> carrying <code>partialText</code> — your UI keeps what it has, and you decide whether to retry.</li><li><strong>Resume on reconnect.</strong> When the gateway supports it, interrupted streams resume from the last received token rather than regenerating from scratch. <span class="VPBadge warning">Planned</span> — v0.1 ships retry-with-partial, resume lands next</li><li><strong>Timeouts that fit LLMs.</strong> Separate connect timeout and <em>inter-chunk</em> timeout (a stream is dead if no token arrives for N seconds — not if the total takes minutes).</li><li><strong>Backgrounding.</strong> On iOS/Android app suspension, streams are cancelled cleanly and the state is surfaced, instead of leaking connections.</li></ul><h2 id="the-demo-we-lead-with" tabindex="-1">The demo we lead with <a class="header-anchor" href="#the-demo-we-lead-with" aria-label="Permalink to &quot;The demo we lead with&quot;">​</a></h2><p>Start a generation, toggle airplane mode mid-stream, toggle it back. The UI keeps the partial text, the SDK retries, the stream completes. That behavior is the difference between a tech demo and a shippable feature.</p><h2 id="retry-semantics" tabindex="-1">Retry semantics <a class="header-anchor" href="#retry-semantics" aria-label="Permalink to &quot;Retry semantics&quot;">​</a></h2><p><code>generate()</code> retries idempotently on connection errors and provider <code>429/5xx</code> with exponential backoff and jitter (configurable). <code>stream()</code> never silently re-issues a request that already produced tokens — you always keep control of whether partial output is regenerated.</p><hr>',10)])])}const u=t(s,[["render",i]]);export{p as __pageData,u as default};
